interface AuthContextType {
    currentStaff: Staff | null;
    login: (email: string, password: string) => { success: boolean; message: string };
    logout: () => void;
    updateCurrentUser: (updates: Partial<Staff>) => void;
    isAuthenticated: boolean;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    // FIX: Import specific hooks instead of using useData which only provides permissions
    const { staff } = useStaff();
    const { addActivityLog } = useActivityLogs();
    const [currentStaff, setCurrentStaff] = useState<Staff | null>(null);

    const login = (email: string, password: string) => {
        const user = staff.find(u => u.email === email && u.password === password);
        if (user) {
            setCurrentStaff(user);
            addActivityLog('Login', `User ${user.fullName} logged in.`, user.id);
            return { success: true, message: 'Login successful' };
