        return { success: false, message: 'Invalid credentials' };
    };

    const logout = () => {
        if (currentStaff) {
            addActivityLog('Logout', `User ${currentStaff.fullName} logged out.`, currentStaff.id);
        }
        setCurrentStaff(null);
    };

    // FIX: Added updateCurrentUser implementation
    const updateCurrentUser = (updates: Partial<Staff>) => {
        if (currentStaff) {
            setCurrentStaff(prev => prev ? ({ ...prev, ...updates }) : null);
        }
    };

    return (
        <AuthContext.Provider value={{
            currentStaff,
            login,
            logout,
            updateCurrentUser,
            isAuthenticated: !!currentStaff
        }}>
            {children}
        </AuthContext.Provider>
    );
};

